function text(s: string) {
  return map(s.split('_'), (word) => {
    return word.slice(0, 1).toUpperCase() + word.slice(1)
  }).join(' ')
}
use({ text })

function trim_start(s: string, char: string = ' '): string {
  if (char === '') return s

  while (s.startsWith(char)) {
    s = s.slice(char.length)
  }
  return s
}

function trim_end(s: string, char: string = ' '): string {
  if (char === '') return s

  while (s.endsWith(char)) {
    s = s.slice(0, -char.length)
  }
  return s
}

function trim(s: string, char: string = ' '): string {
  return trim_end(trim_start(s, char), char)
}

declare global {
  type node = root | id

  type root = number
  type id = string

  type role = 'system' | 'user' | 'assistant' | 'tool'

  type thread_structure = {
    tree: Record<
      node,
      {
        children: node[]
        focus?: node
      }
    >
    roots: root[]
    focus: root
    messages: Record<id, message_structure>
    config?: {
      system_prompt: string
      model: string
      provider: string
    }
  }

  type message_structure = {
    id?: id
    role: role
    content: string
    reasoning?: string
    tools?: tool[]
    usage?: {
      prompt_tokens: number
      completion_tokens: number
      total_tokens: number
    }
    perf?: {
      tokens_per_second: number
      time_to_first_token: number
    }
    has_failed?: bool
    start_time: number
    end_time: number
    model?: string
  }

  type plain_message_structure = {
    role: role
    content: string
  }

  type delta = {
    content: string
    reasoning?: string
  }

  type tool = {
    tool: string
    args: Record<Key, any>
  }

  type thread_index = Record<id, thread_index_item>
  type thread_index_item = {
    title: string
    folder: string
    is_hidden?: boolean
    creation_time?: number
    modification_time?: number
  }

  var text: text
}
